import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.CpLciM8b.js";const k=JSON.parse('{"title":"Self-hosting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/self-hosting.md","filePath":"guide/self-hosting.md","lastUpdated":1787040312000}'),n={name:"guide/self-hosting.md"};function o(r,e,h,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="self-hosting" tabindex="-1">Self-hosting <a class="header-anchor" href="#self-hosting" aria-label="Permalink to &quot;Self-hosting&quot;">​</a></h1><p>Flakemetry self-hosts with a single <code>docker compose up</code>. The compose stack runs the ingestion API, worker, dashboard, PostgreSQL, and a MinIO object store for artifacts.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Docker with Compose v2</li><li>A GitHub OAuth app for dashboard sign-in (below)</li></ul><h2 id="bring-the-stack-up" tabindex="-1">Bring the stack up <a class="header-anchor" href="#bring-the-stack-up" aria-label="Permalink to &quot;Bring the stack up&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AKogut/flakemetry.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flakemetry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;AUTH_SECRET=$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><p>The dashboard is on <a href="http://localhost:3000" target="_blank" rel="noreferrer">localhost:3000</a> and the ingestion API on <a href="http://localhost:4000" target="_blank" rel="noreferrer">localhost:4000</a>, seeded with demo runs.</p><p>The demo dataset is only written when the database is empty, so restarting the stack keeps everything you have ingested. Use <code>pnpm demo</code> when you do want a clean slate.</p><h2 id="github-sign-in" tabindex="-1">GitHub sign-in <a class="header-anchor" href="#github-sign-in" aria-label="Permalink to &quot;GitHub sign-in&quot;">​</a></h2><p>Sign-in uses GitHub OAuth. Create an OAuth app with callback <code>http://localhost:3000/api/auth/callback/github</code>, then set <code>AUTH_GITHUB_ID</code> and <code>AUTH_GITHUB_SECRET</code> in <code>.env</code>. The first account to sign in adopts the seeded workspace.</p><h2 id="see-it-in-60-seconds" tabindex="-1">See it in 60 seconds <a class="header-anchor" href="#see-it-in-60-seconds" aria-label="Permalink to &quot;See it in 60 seconds&quot;">​</a></h2><p>Load the demo dataset — one project&#39;s worth of history with a stable test, two flaky tests, and a regression that AI RCA explains:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # resets the database and seeds the demo dataset in one command</span></span></code></pre></div><p>Then walk the story in the dashboard:</p><ol><li><strong>Flaky board</strong> — every test ranked by a transparent score, worst first.</li><li><strong>Test detail</strong> — that score broken into reason codes (same commit different result · pass-on-rerun · …).</li><li><strong>RCA panel</strong> — the <code>orders</code> regression, explained with a likely cause and a suggested fix.</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Every knob — artifact storage, retention, scoring policy, AI provider — is an environment variable. See the <a href="/flakemetry/v/2026-09-30/reference/configuration">Configuration reference</a> for the complete list, and the <a href="/flakemetry/v/2026-09-30/reference/threat-model">Threat model</a> for the transport and token hardening story.</p><h2 id="production-deployment" tabindex="-1">Production deployment <a class="header-anchor" href="#production-deployment" aria-label="Permalink to &quot;Production deployment&quot;">​</a></h2><h3 id="one-host" tabindex="-1">One host <a class="header-anchor" href="#one-host" aria-label="Permalink to &quot;One host&quot;">​</a></h3><p>The compose stack above is the quickstart: it publishes ports and ships development passwords, and its ports bind to loopback for that reason — Docker publishes straight past the host firewall, so on a machine with a public address the quickstart would put Postgres on the internet.</p><p><a href="https://github.com/AKogut/flakemetry/tree/main/deploy/compose" target="_blank" rel="noreferrer"><code>deploy/compose</code></a> is the version you point a domain at: Caddy terminating TLS with automatic certificates, nothing published but the proxy, and a refusal to start when a secret is missing rather than a fallback to the development password. Its <a href="https://github.com/AKogut/flakemetry/blob/main/deploy/compose/README.md" target="_blank" rel="noreferrer">README</a> covers DNS, the OAuth app, backups, and why the object store needs a public hostname even for traffic that never leaves the machine.</p><h3 id="many-hosts" tabindex="-1">Many hosts <a class="header-anchor" href="#many-hosts" aria-label="Permalink to &quot;Many hosts&quot;">​</a></h3><p>For a horizontally scaled hosted environment there is a <strong>Helm chart</strong> in <a href="https://github.com/AKogut/flakemetry/tree/main/deploy/helm/flakemetry" target="_blank" rel="noreferrer"><code>deploy/helm/flakemetry</code></a>: stateless <code>api</code>/<code>worker</code>/<code>web</code> with HorizontalPodAutoscalers, a pre-install migration hook, and ingress — running against a managed Postgres and object store. The <a href="https://github.com/AKogut/flakemetry/blob/main/deploy/README.md" target="_blank" rel="noreferrer">deploy guide</a> walks the path from zero to a running environment, and the <a href="https://github.com/AKogut/flakemetry/blob/main/deploy/RUNBOOK.md" target="_blank" rel="noreferrer">runbook</a> covers SLOs, scaling, and upgrades.</p>`,23)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
